// Package producer is an independently versioned example producer of static
// Go packages. The examples describe generated API ownership shapes only;
// they do not implement or claim Ruby or Sprig syntax or semantics.
package producer

import "github.com/besmpl/ember/preparedsource"

const rubySource = `// Code generated by the external producer fixture. DO NOT EDIT.
//
// This is an ownership/detachment API shape, not Ruby syntax or semantics.
package rubyshape

// Scope states the deliberately narrow purpose of this generated example.
const Scope = "ownership shape only; no Ruby syntax or semantic compatibility"

// Owner owns all mutable object state.
type Owner struct {
	next uint64
	classes map[uint64]string
}

// Reference is owner-bound and must not cross its Owner's boundary.
type Reference struct {
	owner *Owner
	id uint64
}

// Detached is an application-owned closed record.
type Detached struct {
	ID uint64
	Class string
}

func NewOwner() *Owner { return &Owner{classes: make(map[uint64]string)} }

func (o *Owner) Allocate(class string) Reference {
	o.next++
	o.classes[o.next] = class
	return Reference{owner: o, id: o.next}
}

func (r Reference) Detach() Detached {
	return Detached{ID: r.id, Class: r.owner.classes[r.id]}
}
`

const sprigSource = `// Code generated by the external producer fixture. DO NOT EDIT.
//
// This is a typed functional-composition API shape, not Sprig syntax or semantics.
package sprigshape

// Scope states the deliberately narrow purpose of this generated example.
const Scope = "composition shape only; no Sprig syntax or semantic compatibility"

// Mapper is one typed, effect-explicit transformation.
type Mapper[A, B any] func(A) (B, error)

func Compose[A, B, C any](first Mapper[A, B], second Mapper[B, C]) Mapper[A, C] {
	return func(value A) (C, error) {
		middle, err := first(value)
		if err != nil {
			var zero C
			return zero, err
		}
		return second(middle)
	}
}

func Increment(value int) (int, error) { return value + 1, nil }
func Double(value int) (int, error) { return value * 2, nil }
`

// Sets constructs the two immutable generated packages. reverse varies only
// raw file input order, making canonical identity directly testable.
func Sets(reverse bool) (preparedsource.Set, preparedsource.Set, error) {
	rubyFiles := []preparedsource.File{
		{Name: "ownership.go", Kind: preparedsource.GoFile, Content: rubySource},
		{Name: "scope.go", Kind: preparedsource.GoFile, Content: "package rubyshape\nconst Generated = true\n"},
	}
	sprigFiles := []preparedsource.File{
		{Name: "composition.go", Kind: preparedsource.GoFile, Content: sprigSource},
		{Name: "scope.go", Kind: preparedsource.GoFile, Content: "package sprigshape\nconst Generated = true\n"},
	}
	if reverse {
		rubyFiles[0], rubyFiles[1] = rubyFiles[1], rubyFiles[0]
		sprigFiles[0], sprigFiles[1] = sprigFiles[1], sprigFiles[0]
	}
	rubySet, err := preparedsource.NewSet("rubyshape", rubyFiles)
	if err != nil {
		return preparedsource.Set{}, preparedsource.Set{}, err
	}
	sprigSet, err := preparedsource.NewSet("sprigshape", sprigFiles)
	if err != nil {
		return preparedsource.Set{}, preparedsource.Set{}, err
	}
	return rubySet, sprigSet, nil
}
